'use strict';

const envelope = $input.first()?.json || {};
const input = envelope.payload && typeof envelope.payload === 'object' ? { ...envelope.payload, stateRequestBuilderProfile: String(envelope.profile || '') } : envelope;
const job = input.stateJob && typeof input.stateJob === 'object' ? input.stateJob : input;
const analysisContext = input.analysisContext && typeof input.analysisContext === 'object'
  ? input.analysisContext
  : (input.stateAnalysisContext && typeof input.stateAnalysisContext === 'object' ? input.stateAnalysisContext : {});

const text = (value, limit = 0) => {
  const normalized = String(value ?? '').normalize('NFKC').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return limit > 0 ? normalized.slice(0, limit).trim() : normalized;
};
const asArray = value => Array.isArray(value) ? value : [];
const truthyFlag = value => value === true || value === 1 || ['1', 'true', 'yes', 'on'].includes(text(value, 20).toLowerCase());
const answerText = value => {
  if (typeof value === 'string') return text(value, 4000);
  if (!value || typeof value !== 'object' || Array.isArray(value)) return '';
  return text(
    value.text ?? value.content ?? value.answerText ?? value.answer_text ??
    value.evidenceText ?? value.evidence_text ?? value.message,
    4000
  );
};

const content = text(job.content, 12000);
if (!content) throw new Error('State analysis request: input content is empty.');

const isIsoDate = value => {
  const source = text(value, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(source)) return false;
  const date = new Date(`${source}T00:00:00.000Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === source;
};
const shiftIsoDate = (value, dayOffset) => {
  const date = new Date(`${value}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + dayOffset);
  return date.toISOString().slice(0, 10);
};
const temporalAnchorLocalDate = text(job.localDate || job.local_date, 10);
if (!isIsoDate(temporalAnchorLocalDate)) {
  throw new Error('State analysis request: temporal anchor local date is invalid.');
}
const temporalContext = Object.freeze({
  contractVersion: 'chelsea_state_temporal_context_v1',
  anchorLocalDate: temporalAnchorLocalDate,
  today: temporalAnchorLocalDate,
  yesterday: shiftIsoDate(temporalAnchorLocalDate, -1),
  dayBeforeYesterday: shiftIsoDate(temporalAnchorLocalDate, -2),
  tomorrow: shiftIsoDate(temporalAnchorLocalDate, 1),
  dayAfterTomorrow: shiftIsoDate(temporalAnchorLocalDate, 2),
  latestMutableDate: temporalAnchorLocalDate,
  completedActionsOnly: true,
  futurePlansMutateState: false
});

const contextJson = job.contextJson && typeof job.contextJson === 'object'
  ? job.contextJson
  : (job.context_json && typeof job.context_json === 'object' ? job.context_json : {});
const eventCorrection = contextJson?.message?.eventCorrection && typeof contextJson.message.eventCorrection === 'object'
  ? contextJson.message.eventCorrection
  : null;
const correctionTarget = eventCorrection?.targetEvent && typeof eventCorrection.targetEvent === 'object'
  ? eventCorrection.targetEvent
  : null;
const answerCollections = [
  job.collectedClarificationAnswerSegments,
  job.collected_clarification_answer_segments,
  job.clarificationAnswerSegments,
  job.clarification_answer_segments,
  contextJson.collectedClarificationAnswerSegments,
  contextJson.collected_clarification_answer_segments,
  contextJson.clarificationAnswerSegments,
  contextJson.clarification_answer_segments,
  analysisContext.collectedClarificationAnswerSegments,
  analysisContext.collected_clarification_answer_segments,
  analysisContext.clarificationAnswerSegments,
  analysisContext.clarification_answer_segments
];
const clarificationSession = analysisContext.clarificationSession && typeof analysisContext.clarificationSession === 'object'
  ? analysisContext.clarificationSession
  : (analysisContext.clarification_session && typeof analysisContext.clarification_session === 'object'
      ? analysisContext.clarification_session
      : {});
answerCollections.push(
  clarificationSession.answers,
  clarificationSession.answerSegments,
  clarificationSession.answer_segments
);
for (const clarification of asArray(analysisContext.openClarifications || analysisContext.open_clarifications)) {
  answerCollections.push(
    clarification?.answerSegments,
    clarification?.answer_segments,
    clarification?.answers,
    clarification?.answerText,
    clarification?.answer_text
  );
}
const collectedClarificationAnswerSegments = [];
const seenAnswerSegments = new Set();
let collectedAnswerCharacters = 0;
for (const collection of answerCollections) {
  const values = Array.isArray(collection) ? collection : [collection];
  for (const value of values) {
    const segment = answerText(value);
    if (!segment || seenAnswerSegments.has(segment) || collectedAnswerCharacters + segment.length > 12000) continue;
    seenAnswerSegments.add(segment);
    collectedClarificationAnswerSegments.push(segment);
    collectedAnswerCharacters += segment.length;
    if (collectedClarificationAnswerSegments.length >= 20) break;
  }
  if (collectedClarificationAnswerSegments.length >= 20) break;
}

const rawAnalysisMode = text(
  job.analysisMode ?? job.analysis_mode ?? input.analysisMode ?? input.analysis_mode ??
  contextJson.analysisMode ?? contextJson.analysis_mode,
  80
).toLowerCase();
const forceNeutralWithoutClarification = [
  job.forceNeutralWithoutClarification,
  job.force_neutral_without_clarification,
  input.forceNeutralWithoutClarification,
  input.force_neutral_without_clarification,
  contextJson.forceNeutralWithoutClarification,
  contextJson.force_neutral_without_clarification
].some(truthyFlag);
const analysisMode = forceNeutralWithoutClarification || rawAnalysisMode === 'neutral_without_clarification'
  ? 'neutral_without_clarification'
  : 'standard';

const sphereCodes = ['health','energy','mood','calm','clarity','motivation','relationships','progress','inspiration','finance'];
const dayClasses = [1, 3, 7, 14];
const impactBases = ['explicit', 'clarified_inference', 'neutral_assumption'];
const impactScales = [0.1, 0.35, 0.65, 1];
const polarityModes = ['positive_only', 'negative_only', 'mixed_allowed', 'mixed_required', 'any'];
const clarificationModes = ['none', 'ask_if_missing', 'required_before_apply'];
const financeModes = ['forbidden', 'realized_only'];
const codePattern = /^[a-z][a-z0-9_]{1,63}$/;
const numericArray = value => asArray(value).map(Number).filter(Number.isFinite);
const stringArray = value => asArray(value).map(item => text(item, 160)).filter(Boolean);
const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const integerVersion = value => {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed >= 1 ? parsed : null;
};

const rawRuleCatalog = analysisContext.ruleCatalog || analysisContext.rule_catalog ||
  contextJson.ruleCatalog || contextJson.rule_catalog || {};
const rawRules = asArray(rawRuleCatalog.rules || rawRuleCatalog.ruleDefinitions || rawRuleCatalog.rule_definitions);
const ruleCatalogContractVersion = text(
  rawRuleCatalog.contractVersion || rawRuleCatalog.contract_version,
  80
);
const ruleSetCode = text(rawRuleCatalog.ruleSetCode || rawRuleCatalog.rule_set_code, 64);
const ruleSetVersion = integerVersion(rawRuleCatalog.ruleSetVersion ?? rawRuleCatalog.rule_set_version);
const ruleCatalogVersion = integerVersion(
  rawRuleCatalog.ruleCatalogVersion ?? rawRuleCatalog.rule_catalog_version ??
  rawRuleCatalog.catalogVersion ?? rawRuleCatalog.catalog_version ??
  rawRuleCatalog.version
);
const catalogErrors = [];
if (ruleCatalogContractVersion !== 'chelsea_state_rule_catalog_v1') {
  catalogErrors.push('contract_version_invalid');
}
if (!codePattern.test(ruleSetCode)) catalogErrors.push('rule_set_code_invalid');
if (ruleSetVersion === null) catalogErrors.push('rule_set_version_invalid');
if (ruleCatalogVersion === null) catalogErrors.push('rule_catalog_version_invalid');
const sphereDefaults = [];
const seenDefaultSpheres = new Set();
for (const [index, rawDefault] of asArray(rawRuleCatalog.sphereDefaults || rawRuleCatalog.sphere_defaults).entries()) {
  const sphereCode = text(rawDefault?.sphereCode || rawDefault?.sphere_code, 40);
  const durationDays = Number(rawDefault?.durationDays ?? rawDefault?.duration_days);
  if (!sphereCodes.includes(sphereCode) || !dayClasses.includes(durationDays) || seenDefaultSpheres.has(sphereCode)) {
    catalogErrors.push(`sphere_default_${index}_invalid`);
    continue;
  }
  seenDefaultSpheres.add(sphereCode);
  sphereDefaults.push({ sphereCode, durationDays });
}
if (sphereDefaults.length !== sphereCodes.length) catalogErrors.push('sphere_defaults_incomplete');

const normalizedRules = [];
for (const [index, rawRule] of rawRules.entries()) {
  if (!rawRule || typeof rawRule !== 'object' || Array.isArray(rawRule)) {
    catalogErrors.push(`rule_${index}_invalid`);
    continue;
  }
  const ruleCode = text(rawRule.ruleCode || rawRule.rule_code, 64);
  const rawActive = own(rawRule, 'active')
    ? rawRule.active
    : (own(rawRule, 'isActive') ? rawRule.isActive : rawRule.is_active);
  if (typeof rawActive !== 'boolean') {
    catalogErrors.push(`rule_${index}_active_invalid`);
    continue;
  }
  const active = rawActive;
  if (!active) continue;
  const rawEventClasses = rawRule.eventClasses || rawRule.event_classes ||
    (rawRule.eventClass || rawRule.event_class ? [rawRule.eventClass || rawRule.event_class] : []);
  const normalizedEventClasses = [...new Set(stringArray(rawEventClasses))];
  const polarityMode = text(rawRule.polarityMode || rawRule.polarity_mode, 40);
  const allowedImpactScales = [...new Set(numericArray(rawRule.allowedImpactScales || rawRule.allowed_impact_scales))];
  const neutralScale = Number(rawRule.neutralScale ?? rawRule.neutral_scale);
  const maxEffects = Number(rawRule.maxEffects ?? rawRule.max_effects);

  const allowedEffects = [];
  const rawAllowedEffects = rawRule.allowedEffects || rawRule.allowed_effects ||
    rawRule.effects?.allowed || rawRule.effects_policy?.allowed;
  for (const rawEffect of asArray(rawAllowedEffects)) {
    allowedEffects.push({
      effectRuleCode: text(rawEffect?.effectRuleCode || rawEffect?.effect_rule_code, 64),
      sphereCode: text(rawEffect?.sphereCode || rawEffect?.sphere_code, 40),
      direction: Number(rawEffect?.direction),
      minStrength: Number(rawEffect?.minStrength ?? rawEffect?.min_strength),
      defaultStrength: Number(rawEffect?.defaultStrength ?? rawEffect?.default_strength),
      maxStrength: Number(rawEffect?.maxStrength ?? rawEffect?.max_strength),
      minConfidence: Number(rawEffect?.minConfidence ?? rawEffect?.min_confidence),
      defaultConfidence: Number(rawEffect?.defaultConfidence ?? rawEffect?.default_confidence),
      maxConfidence: Number(rawEffect?.maxConfidence ?? rawEffect?.max_confidence),
      baseWeight: Number(rawEffect?.baseWeight ?? rawEffect?.base_weight),
      allowedDurationDays: [...new Set(numericArray(
        rawEffect?.allowedDurationDays || rawEffect?.allowed_duration_days
      ))],
      allowedImpactBases: [...new Set(stringArray(
        rawEffect?.allowedImpactBases || rawEffect?.allowed_impact_bases
      ))],
      requiresLiteralEvidence: rawEffect?.requiresLiteralEvidence ?? rawEffect?.requires_literal_evidence,
      requiresRealizedOutcome: rawEffect?.requiresRealizedOutcome ?? rawEffect?.requires_realized_outcome
    });
  }

  const requiredEffectGroups = [];
  const rawRequiredGroups = rawRule.requiredEffectGroups || rawRule.required_effect_groups ||
    rawRule.requiredEffects || rawRule.required_effects ||
    rawRule.effects?.requiredGroups || rawRule.effects_policy?.required_groups;
  for (const rawGroup of asArray(rawRequiredGroups)) {
    requiredEffectGroups.push({
      groupCode: text(rawGroup?.groupCode || rawGroup?.group_code, 64),
      minCount: Number(rawGroup?.minCount ?? rawGroup?.min_count),
      maxCount: Number(rawGroup?.maxCount ?? rawGroup?.max_count),
      effectRuleCodes: [...new Set(stringArray(rawGroup?.effectRuleCodes || rawGroup?.effect_rule_codes))],
      sphereCodes: [...new Set(stringArray(rawGroup?.sphereCodes || rawGroup?.sphere_codes))],
      directions: [...new Set(numericArray(rawGroup?.directions || (rawGroup?.direction !== undefined ? [rawGroup.direction] : [])))]
    });
  }

  const rawClarification = rawRule.clarificationPolicy || rawRule.clarification_policy || {};
  const requiredSlots = [];
  for (const rawSlot of asArray(rawClarification.requiredSlots || rawClarification.required_slots)) {
    if (typeof rawSlot === 'string') {
      requiredSlots.push({ slotCode: text(rawSlot, 64), label: text(rawSlot, 160) });
    } else {
      requiredSlots.push({
        slotCode: text(rawSlot?.slotCode || rawSlot?.slot_code || rawSlot?.code, 64),
        label: text(rawSlot?.label || rawSlot?.description || rawSlot?.slotCode || rawSlot?.slot_code, 200)
      });
    }
  }
  const questions = [];
  for (const rawQuestion of asArray(rawClarification.questions)) {
    const options = [];
    for (const rawOption of asArray(rawQuestion?.options)) {
      options.push({
        optionCode: text(rawOption?.optionCode || rawOption?.option_code || rawOption?.code, 64),
        label: text(rawOption?.label || rawOption?.text, 160)
      });
    }
    questions.push({
      questionCode: text(rawQuestion?.questionCode || rawQuestion?.question_code || rawQuestion?.code, 64),
      slotCodes: [...new Set(stringArray(rawQuestion?.slotCodes || rawQuestion?.slot_codes))],
      questionText: text(rawQuestion?.questionText || rawQuestion?.question_text || rawQuestion?.text, 500),
      options
    });
  }
  const clarificationPolicy = {
    mode: text(rawClarification.mode, 40),
    requiredSlots,
    questions
  };

  const rawFinance = rawRule.financePolicy || rawRule.finance_policy || {};
  const financeOutcomes = [];
  for (const rawOutcome of asArray(rawFinance.outcomes || rawFinance.allowedOutcomes || rawFinance.allowed_outcomes)) {
    if (typeof rawOutcome === 'string') {
      financeOutcomes.push({ outcomeType: text(rawOutcome, 64), directions: [-1, 1], evidencePatterns: [] });
    } else {
      financeOutcomes.push({
        outcomeType: text(rawOutcome?.outcomeType || rawOutcome?.outcome_type, 64),
        directions: [...new Set(numericArray(rawOutcome?.directions || (rawOutcome?.direction !== undefined ? [rawOutcome.direction] : [])))],
        evidencePatterns: stringArray(rawOutcome?.evidencePatterns || rawOutcome?.evidence_patterns)
      });
    }
  }
  const financePolicy = {
    mode: text(rawFinance.mode, 40),
    evidenceRequired: rawFinance.evidenceRequired ?? rawFinance.evidence_required,
    realizedEvidenceRequired: rawFinance.realizedEvidenceRequired ?? rawFinance.realized_evidence_required,
    outcomes: financeOutcomes
  };

  if (!codePattern.test(ruleCode)) catalogErrors.push(`rule_${index}_code_invalid`);
  if (!normalizedEventClasses.length || normalizedEventClasses.some(value => !codePattern.test(value))) {
    catalogErrors.push(`rule_${index}_event_classes_invalid`);
  }
  if (!polarityModes.includes(polarityMode)) catalogErrors.push(`rule_${index}_polarity_invalid`);
  if (!allowedImpactScales.length || allowedImpactScales.some(value => !impactScales.includes(value))) {
    catalogErrors.push(`rule_${index}_impact_scales_invalid`);
  }
  if (!impactScales.includes(neutralScale) || !allowedImpactScales.includes(neutralScale)) {
    catalogErrors.push(`rule_${index}_neutral_scale_invalid`);
  }
  if (!Number.isInteger(maxEffects) || maxEffects < 1 || maxEffects > 4) catalogErrors.push(`rule_${index}_max_effects_invalid`);
  if (!allowedEffects.length || allowedEffects.some(value =>
    !codePattern.test(value.effectRuleCode) ||
    !sphereCodes.includes(value.sphereCode) ||
    ![-1, 1].includes(value.direction) ||
    !Number.isInteger(value.minStrength) || !Number.isInteger(value.defaultStrength) || !Number.isInteger(value.maxStrength) ||
    value.minStrength < 1 || value.maxStrength > 3 ||
    value.defaultStrength < value.minStrength || value.defaultStrength > value.maxStrength ||
    !Number.isFinite(value.minConfidence) || !Number.isFinite(value.defaultConfidence) || !Number.isFinite(value.maxConfidence) ||
    value.minConfidence < 0.60 || value.maxConfidence > 1 ||
    value.defaultConfidence < value.minConfidence || value.defaultConfidence > value.maxConfidence ||
    !Number.isFinite(value.baseWeight) || value.baseWeight < 0.5 || value.baseWeight > 1.5 ||
    !value.allowedDurationDays.length || value.allowedDurationDays.some(day => !dayClasses.includes(day)) ||
    !value.allowedImpactBases.length || value.allowedImpactBases.some(basis => !impactBases.includes(basis)) ||
    typeof value.requiresLiteralEvidence !== 'boolean' ||
    typeof value.requiresRealizedOutcome !== 'boolean' ||
    (value.requiresRealizedOutcome && value.sphereCode !== 'finance')
  )) catalogErrors.push(`rule_${index}_allowed_effects_invalid`);
  const allowedEffectCodes = allowedEffects.map(value => value.effectRuleCode);
  const allowedEffectPairs = allowedEffects.map(value => `${value.sphereCode}:${value.direction}`);
  if (new Set(allowedEffectCodes).size !== allowedEffectCodes.length ||
    new Set(allowedEffectPairs).size !== allowedEffectPairs.length) {
    catalogErrors.push(`rule_${index}_allowed_effects_duplicate`);
  }
  if (requiredEffectGroups.some(group =>
    !codePattern.test(group.groupCode) ||
    !Number.isInteger(group.minCount) || group.minCount < 0 ||
    !Number.isInteger(group.maxCount) || group.maxCount < group.minCount || group.maxCount > 10 ||
    !group.effectRuleCodes.length || group.effectRuleCodes.some(value => !allowedEffectCodes.includes(value)) ||
    !group.sphereCodes.length || group.sphereCodes.some(value => !sphereCodes.includes(value)) ||
    !group.directions.length || group.directions.some(direction => ![-1, 1].includes(direction)) ||
    group.maxCount > group.effectRuleCodes.length ||
    group.effectRuleCodes.some(effectRuleCode => {
      const permission = allowedEffects.find(value => value.effectRuleCode === effectRuleCode);
      return !permission || !group.sphereCodes.includes(permission.sphereCode) ||
        !group.directions.includes(permission.direction);
    })
  )) catalogErrors.push(`rule_${index}_required_groups_invalid`);
  if (new Set(requiredEffectGroups.map(group => group.groupCode)).size !== requiredEffectGroups.length) {
    catalogErrors.push(`rule_${index}_required_groups_duplicate`);
  }
  const slotCodes = requiredSlots.map(slot => slot.slotCode);
  const questionCodes = questions.map(question => question.questionCode);
  if (!clarificationModes.includes(clarificationPolicy.mode) ||
    requiredSlots.some(slot => !codePattern.test(slot.slotCode) || !slot.label) ||
    questions.some(question => !codePattern.test(question.questionCode) ||
      !question.slotCodes.length || question.slotCodes.some(code => !requiredSlots.some(slot => slot.slotCode === code)) ||
      !question.questionText || !question.options.length ||
      question.options.some(option => !codePattern.test(option.optionCode) || !option.label) ||
      new Set(question.options.map(option => option.optionCode)).size !== question.options.length
    )) catalogErrors.push(`rule_${index}_clarification_policy_invalid`);
  if (new Set(slotCodes).size !== slotCodes.length || new Set(questionCodes).size !== questionCodes.length ||
    (clarificationPolicy.mode !== 'none' && (!requiredSlots.length || !questions.length)) ||
    (clarificationPolicy.mode === 'none' && (requiredSlots.length || questions.length))) {
    catalogErrors.push(`rule_${index}_clarification_policy_duplicate_or_empty`);
  }
  if (!financeModes.includes(financePolicy.mode) ||
    typeof financePolicy.evidenceRequired !== 'boolean' ||
    typeof financePolicy.realizedEvidenceRequired !== 'boolean') {
    catalogErrors.push(`rule_${index}_finance_mode_invalid`);
  }
