    !outcome.directions.length || outcome.directions.some(direction => ![-1, 1].includes(direction)) ||
    (financePolicy.realizedEvidenceRequired && !outcome.evidencePatterns.length)
  ))) catalogErrors.push(`rule_${index}_finance_outcomes_invalid`);
