    outcome.directions.map(direction => `${outcome.outcomeType}:${direction}`)
  );
  if (new Set(financeOutcomeDirectionPairs).size !== financeOutcomeDirectionPairs.length) {
    catalogErrors.push(`rule_${index}_finance_outcomes_duplicate`);
  }
  for (const outcome of financePolicy.outcomes) {
    for (const pattern of outcome.evidencePatterns) {
      try { new RegExp(pattern, 'iu'); }
      catch { catalogErrors.push(`rule_${index}_finance_pattern_invalid`); }
    }
  }

  normalizedRules.push({
    ruleCode,
    active: true,
    eventClasses: normalizedEventClasses,
    polarityMode,
    allowedEffects,
    requiredEffectGroups,
    allowedImpactScales,
    neutralScale,
    maxEffects,
    clarificationPolicy,
    financePolicy
  });
}
if (!normalizedRules.length) catalogErrors.push('active_rules_missing');
if (new Set(normalizedRules.map(rule => rule.ruleCode)).size !== normalizedRules.length) catalogErrors.push('active_rule_code_duplicate');
if (catalogErrors.length) {
  throw new Error(`State analysis request: rule catalog invalid (${[...new Set(catalogErrors)].join(',')}).`);
}
const ruleCatalog = {
  contractVersion: 'chelsea_state_rule_catalog_v1',
  ruleSetCode,
  ruleSetVersion,
  ruleCatalogVersion,
  sphereDefaults,
  rules: normalizedRules
};
const activeRuleCodes = normalizedRules.map(rule => rule.ruleCode);
const activeEffectRuleCodes = normalizedRules.flatMap(rule =>
  rule.allowedEffects.map(effect => effect.effectRuleCode)
);
const catalogEventClasses = [...new Set(normalizedRules.flatMap(rule => rule.eventClasses))];
const financeOutcomeTypes = [...new Set(normalizedRules.flatMap(rule =>
  rule.financePolicy.outcomes.map(outcome => outcome.outcomeType)
))];
