const effectSchema = {
  type: 'object',
  properties: {
    effectRuleCode: { type: 'string', enum: activeEffectRuleCodes },
    sphereCode: { type: 'string', enum: sphereCodes },
    direction: { type: 'integer', enum: [-1, 1] },
    strength: { type: 'integer', enum: [1, 2, 3] },
