    financeEvidenceText: nullableString,
    durationDays: { type: 'integer', enum: dayClasses },
    durationBasis: { type: 'string', enum: ['sphere_default', 'explicit_user_duration'] },
    durationEvidence: nullableString,
    impactReason: { type: 'string' },
    durationReason: { type: 'string' },
    evidencePoints: { type: 'number', minimum: 0, maximum: 10 },
