  required: [
    'effectRuleCode','sphereCode','direction','strength','confidence','impactBasis','impactScale',
    'financeOutcomeType','financeEvidenceText',
    'durationDays','durationBasis','durationEvidence','impactReason','durationReason',
    'evidencePoints','supersedesEffectId','expectedSupersededVersion','supersedeReason'
  ],
  additionalProperties: false
};

const eventSchema = {
  type: 'object',
  properties: {
    clientRef: { type: 'string' },
    eventTypeCode: { type: 'string' },
    eventClass: { type: 'string', enum: catalogEventClasses },
    ruleCode: { type: 'string', enum: activeRuleCodes },
    ruleSetVersion: { type: 'integer', enum: [ruleSetVersion] },
    dailySemanticKey: {
      type: 'string',
