    score: { type: 'integer', minimum: 1, maximum: 10 },
    startsOn: { type: 'string' },
    durationDays: { type: 'integer', enum: dayClasses },
    evidenceText: { type: 'string' },
    temporalEvidenceText: { type: 'string' },
    supersedesUserScoreId: nullableString,
