  },
  required: [
    'sphereCode','score','startsOn','durationDays','evidenceText','temporalEvidenceText',
    'supersedesUserScoreId','expectedSupersededVersion'
  ],
  additionalProperties: false
};

const retractionSchema = {
  type: 'object',
  properties: {
    targetEffectId: { type: 'string' },
    expectedVersion: { type: 'integer', minimum: 0 },
    reason: { type: 'string' }
  },
